package com.hms.appointments;
import com.hms.doctors.*; import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/public/hospitals/{tenantSlug}/appointments") public class PublicAppointmentController {private final TenantRepository tenants;private final DoctorRepository doctors;private final PatientRepository patients;private final AppointmentRepository appointments;private final BookingPolicyService bookingPolicy;public PublicAppointmentController(TenantRepository t,DoctorRepository d,PatientRepository p,AppointmentRepository a,BookingPolicyService b){tenants=t;doctors=d;patients=p;appointments=a;bookingPolicy=b;} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Appointment book(@PathVariable String tenantSlug,@Valid @RequestBody PublicAppointmentRequest r){UUID tenant=tenants.findBySlug(tenantSlug).filter(t->t.getStatus()!=TenantStatus.SUSPENDED&&t.getStatus()!=TenantStatus.CANCELLED&&t.getStatus()!=TenantStatus.EXPIRED).map(Tenant::getId).orElseThrow(()->new IllegalArgumentException("Hospital is not accepting appointments"));if(!r.endsAt().isAfter(r.startsAt()))throw new IllegalArgumentException("endsAt must be after startsAt");doctors.findById(r.doctorId()).filter(d->d.getTenantId().equals(tenant)&&d.isActive()&&d.isPublicVisible()).orElseThrow(()->new IllegalArgumentException("Doctor is not available for public booking"));if(appointments.existsByTenantIdAndDoctorIdAndStartsAtAndStatusNot(tenant,r.doctorId(),r.startsAt(),AppointmentStatus.CANCELLED))throw new IllegalArgumentException("Doctor slot is already booked");CreateAppointmentRequest request=new CreateAppointmentRequest(r.fullName(),r.phone(),r.hospitalPatientId(),r.abhaId(),r.doctorId(),r.startsAt(),r.endsAt(),AppointmentSource.PUBLIC,r.reason(),r.notes());bookingPolicy.validate(tenant,request);Patient patient=patients.findFirstByTenantIdAndPhoneOrderByCreatedAtAsc(tenant,r.phone()).orElseGet(()->patients.save(new Patient(tenant,request)));return appointments.save(new Appointment(tenant,patient.getId(),request));}}
